import pandas as pdimport numpy as npfrom sklearn.model_selection import StratifiedShuffleSplitfrom sklearn.pipeline import Pipelinefrom sklearn.compose import ColumnTransformerfrom sklearn.impute import SimpleImputerfrom sklearn.preprocessing import StandardScaler, OneHotEncoderhousing=pd.read_csv("dataset/housing.csv")print(housing)# 2. Create a stratified test set based on income categoryhousing["income_cat"] = pd.cut(    housing["median_income"],    bins=[0., 1.5, 3.0, 4.5, 6., np.inf],    labels=[1, 2, 3, 4, 5])split=StratifiedShuffleSplit(n_splits=1,test_size=0.2,random_state=42)for train_index, test_index in split.split(housing,housing['income_cat']):    start_train_set=housing.loc[train_index].drop("income_cat",axis=1)  #We will work on this data    start_test_set = housing.loc[test_index].drop("income_cat", axis=1) #Set aside the test data# we will work on the copy of training data.housing=start_train_set.copy()# separate feature and labels?housing_labels=housing["median_house_value"].copy()housing=housing.drop("median_house_value",axis=1)print(housing,housing_labels)#Separate numerical and categorical columnsnum_att=housing.drop("ocean_proximity",axis=1).columns.tolist()cat_att=["ocean_proximity"]#Let's make the Pipeline# for numerical columnsnum_pipeline=Pipeline([    ("imputer",SimpleImputer(strategy="median")),    ("Scaler",StandardScaler())])# for categorical columnscat_pipeline=Pipeline([    ("onehot",OneHotEncoder(handle_unknown="ignore"))])# Construct the full pipelinefull_pipeline=ColumnTransformer([    ("num",num_pipeline,num_att),    ("cat",cat_pipeline,cat_att)])# transfer the datahousing_pre=full_pipeline.fit_transform(housing)print(housing_pre.shape)